export default function StudentList({ students, onSelect }) {
  return (
    <div className="card">
      <h3>Student List</h3>

      {students.length === 0 && <p>No students added yet.</p>}

      <ul className="list">
        {students.map((s) => (
          <li key={s.id} onClick={() => onSelect(s)}>
            <span>{s.name}</span>
            <span className="marks">{s.marks}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}
